    18                          if (nl == CSV_LINES)
    19                                  return tf != 0 && tf == nf;
    20  #endif
    21                          if (tf == 0) {
    22                                  // First time and no fields, give up
    23                                  if (nf == 0)
    24                                          return 0;
    25                                  // First time, set the number of fields
    26                                  tf = nf;
    27                          } else if (tf != nf) {
    28                                  // Field number mismatch, we are done.
    29                                  return 0;
    30                          }
    31                          nf = 0;
    32                          break;
    33                  default:
    34                          break;
    35                  }
    36          }
    37          return tf && nl > 2;
    38  }
